        end)
    end
    self. collectDataTable = CollectDataManager:Get():GetCollectDataTable()
    CommonHelper:InitMoreRowScrollView(self.ScrollView_V,  # self. collectDataTable, 1,function(dataIndex, itemObj, scroll)
        self:UpdateScrollView_V(itemObj,dataIndex)
    end)
end
