function Page_CommonActCollectWordsView:UpdateScrollView_V(itemObj,index)
    local tableIndex = index+1
    ---@type CollectData
    local collectData = CollectDataManager:Get():GetCollectDataByIndex(tableIndex)
    local propType ,configData = CommonHelper:GetPropTypeById(tonumber(collectData.exchangePropId))
    local name =""
    if propType==PropType.TracKSegment then
        name = configData.name
    elseif propType==PropType.Part then
        name=configData.partname
    elseif propType==PropType.Article then
        name=configData.name
    end
   local article= UIUtil.GetChild("ItemCom_118",itemObj)
    local param = Param_ItemArticleParam()
    CommonHelper:SetItemComGroup(article, UIModuleID.CommonActCollectWords, collectData.exchangePropId, param, function(btnData)
        CommonHelper:ShowPartInfoByCfgId(btnData, UIModuleID.CommonActCollectWords, false)
    end, collectData.exchangePropId)
    CommonHelper:SetText("###itemNum",itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordNumSplit),ClientDataManager:Get():GetTemplateString(name) ,collectData.exchangePropNum))
    CommonHelper:SetText("###exchtext",itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordLimitSplit),collectData.exchangeLimit - collectData.exchangeSum))
    CommonHelper:HButtonSetCallback("BtnExch",itemObj,function()
        if  collectData.exchangeSum < collectData.exchangeLimit then
            if collectData:IsCanExchange() then
                CommonFestivalSubSystem:Get():SendMsg_ActWordGift(collectData.configIndex,self.actConfig.C_ID)
            else
                CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordNotEnough))
            end
        else
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordUpLimit))
        end
    end)
    local ScrollView_H= UIUtil.GetTypeChildWightInputPath("ScrollView_H", itemObj, typeof(MoreRowScrollView))
    CommonHelper:InitMoreRowScrollView(ScrollView_H,  #collectData:GetNeedPropTable(), 1,function(wordIndex, wordItem, scroll)
        local propsTable= collectData:GetNeedPropTable()
        local num = KnapsackDataManager:Get():GetArticleCountByCfgid(propsTable[wordIndex+1])
        ---@type article_config_cell
        local articleWordData = CommonHelper:GetTableDataByID(ConfigNames.article_config,propsTable[wordIndex+1])
        CommonHelper:SetText("###wordNum",wordItem,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordNumSplitWord),num ,1))
        CommonHelper:GetComponentSetUITexture("wordIcon", wordItem,articleWordData.NewIcon, self:GetUIModuleID())
        CommonHelper:HButtonSetCallback("detailsBtn",wordItem,function()
            CommonHelper:ShowPartInfoByCfgId(tonumber(propsTable[wordIndex+1]), UIModuleID.CommonActCollectWords, false)
        end)
    end)
end

